package utils;

import constants.Base;
import constants.Constants;
import constants.Message;

/**
 * Kiem du lieu nhap: lua chon menu, gia tri khong rong, chu so dung he.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Constructor private: lop chi co ham static
    private Validation() {
    }

    // Kiem lua chon menu la so nguyen trong [min, max]
    public static int getChoice(String input, int min, int max) throws Exception {
        // Bien giu so nguoi dung chon
        int choice = 0;

        // Doi chuoi sang so nguyen
        try {
            choice = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong thi bao phai nhap so
            throw new Exception(Message.INVALID_NUMBER);
        }

        // Ngoai khoang cho phep thi bao khoang dung
        if ((choice < min) || (choice > max)) {
            throw new Exception(String.format(Message.INVALID_RANGE, min, max));
        }

        // Hop le thi tra ve so da chon
        return choice;
    }

    // Kiem gia tri can doi khong duoc rong
    public static String getValue(String input) throws Exception {
        // Rong sau khi bo dau cach thi bao loi
        if (input.trim().isEmpty()) {
            throw new Exception(Message.EMPTY_VALUE);
        }

        // Tra ve gia tri da bo dau cach thua
        return input.trim();
    }

    // Kiem moi chu so deu thuoc he (vd he 2 chi co 0 va 1)
    public static void checkValue(String value, Base base) throws Exception {
        // Viet hoa de a-f cung hop le nhu A-F
        String digits = value.toUpperCase();

        // Co dau - hoac + o dau thi bo dau di
        if (digits.startsWith(Constants.MINUS) || digits.startsWith(Constants.PLUS)) {
            digits = digits.substring(1);
        }

        // Chi co dau ma khong co chu so thi bao loi
        if (digits.isEmpty()) {
            throw new Exception(String.format(Message.INVALID_VALUE, value, base.getLabel(),
                    base.getLabel(), base.getAllowedDigits()));
        }

        // Kiem tung chu so
        for (int i = 0; i < digits.length(); i++) {
            // Gia tri cua chu so (-1 neu khong phai chu so)
            int digitValue = Constants.DIGITS.indexOf(digits.charAt(i));

            // Khong phai chu so, hoac lon hon co so cho phep thi bao loi
            if ((digitValue < 0) || (digitValue >= base.getRadix())) {
                throw new Exception(String.format(Message.INVALID_VALUE, value, base.getLabel(),
                        base.getLabel(), base.getAllowedDigits()));
            }
        }
    }
}

